#include <stdio.h>

#define DEBUG 0

int main(void)
{
    #ifdef DEBUG
        puts("DEBUG is defined");
    #endif
    #if DEBUG
        puts("debug enabled");
    #else
        puts("debug disabled");
    #endif
    return 0;
}

#include <stdio.h>

#define ROOM_SIZE 30

int main(void)
{
    #if ROOM_SIZE >= 50
        puts("large room");
    #elif ROOM_SIZE >= 20
        puts("medium room");
    #else
        puts("small room");
    #endif
    return 0;
}

#include <stdio.h>

#ifndef DEBUG
#define DEBUG 0
#endif

int main(void)
{
    #if DEBUG
        puts("trace: entering main");
    #endif
    puts("Result: 12");
    return 0;
}

examQuestions.question:
Trace a zero-valued but present DEBUG macro.

#include <stdio.h>

#define DEBUG 0

int main(void)
{
    #ifdef DEBUG
        puts("DEBUG is defined");
    #endif
    #if DEBUG
        puts("debug enabled");
    #else
        puts("debug disabled");
    #endif
    return 0;
}
